import React, { useState, useEffect } from 'react';
import Navbar from '../components/Navbar';
import { 
  FaPlus, FaTrash, FaCalendarAlt, FaClock, FaBrain, 
  FaChartLine, FaCheckCircle, FaCircle, FaBook, FaClipboardList,
  FaBriefcase, FaUsers, FaFire, FaSmile, FaMeh, FaFrown,
  FaPlay, FaPause, FaRedo, FaStopwatch
} from 'react-icons/fa';

function AcademicLoad() {
  const [items, setItems] = useState([]);
  const [showAddForm, setShowAddForm] = useState(false);
  const [aiInsight, setAiInsight] = useState('');
  const [completionRate, setCompletionRate] = useState(0);
  const [stressLevel, setStressLevel] = useState('medium');
  const [timerActive, setTimerActive] = useState(false);
  const [timerSeconds, setTimerSeconds] = useState(0);
  const [timerMode, setTimerMode] = useState('focus'); // focus or break
  const [newItem, setNewItem] = useState({
    title: '',
    type: 'exam',
    dueDate: '',
    dueTime: '',
    priority: 'medium',
    completed: false
  });

  // Timer effect
  useEffect(() => {
    let interval;
    if (timerActive && timerSeconds > 0) {
      interval = setInterval(() => {
        setTimerSeconds(prev => prev - 1);
      }, 1000);
    } else if (timerActive && timerSeconds === 0) {
      setTimerActive(false);
      // Auto switch mode when timer ends
      if (timerMode === 'focus') {
        setTimerMode('break');
        setTimerSeconds(5 * 60);
        setTimerActive(true);
      }
    }
    return () => clearInterval(interval);
  }, [timerActive, timerSeconds, timerMode]);

  useEffect(() => {
    const saved = localStorage.getItem('academicLoad');
    if (saved) {
      const loadedItems = JSON.parse(saved);
      setItems(loadedItems);
      calculateStats(loadedItems);
      generateAIInsight(loadedItems);
    }
  }, []);

  const calculateStats = (taskList) => {
    const completed = taskList.filter(i => i.completed).length;
    const rate = taskList.length > 0 ? Math.round((completed / taskList.length) * 100) : 0;
    setCompletionRate(rate);
    
    const pendingHigh = taskList.filter(i => !i.completed && i.priority === 'high').length;
    if (pendingHigh >= 3) setStressLevel('high');
    else if (pendingHigh >= 1) setStressLevel('medium');
    else setStressLevel('low');
  };

  const generateAIInsight = (taskList) => {
    const pending = taskList.filter(i => !i.completed);
    const highPriority = pending.filter(i => i.priority === 'high');
    const dueSoon = pending.filter(i => {
      if (!i.dueDate) return false;
      const dueDate = new Date(i.dueDate);
      const today = new Date();
      const diffTime = dueDate - today;
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
      return diffDays <= 3 && diffDays >= 0;
    });
    
    let insight = '';
    if (pending.length === 0) {
      insight = '🎉 Amazing! All tasks completed. Take a well-deserved break!';
    } else if (highPriority.length >= 2) {
      insight = `🧠 You have ${highPriority.length} high-priority tasks. Use the focus timer below!`;
    } else if (dueSoon.length > 0) {
      insight = `📅 ${dueSoon.length} task(s) due soon. Stay on track!`;
    } else if (pending.length >= 5) {
      insight = `📚 Heavy workload detected. Take short breaks to avoid burnout.`;
    } else {
      insight = `💡 You're making great progress! Keep the momentum going.`;
    }
    setAiInsight(insight);
  };

  const saveToLocal = (newItems) => {
    setItems(newItems);
    localStorage.setItem('academicLoad', JSON.stringify(newItems));
    calculateStats(newItems);
    generateAIInsight(newItems);
  };

  const addItem = () => {
    if (newItem.title && newItem.dueDate) {
      const newItems = [...items, { ...newItem, id: Date.now() }];
      saveToLocal(newItems);
      setNewItem({ title: '', type: 'exam', dueDate: '', dueTime: '', priority: 'medium', completed: false });
      setShowAddForm(false);
    }
  };

  const toggleComplete = (id) => {
    const newItems = items.map(item => item.id === id ? { ...item, completed: !item.completed } : item);
    saveToLocal(newItems);
  };

  const deleteItem = (id) => {
    const newItems = items.filter(item => item.id !== id);
    saveToLocal(newItems);
  };

  const startTimer = () => {
    if (timerSeconds === 0) {
      setTimerSeconds(timerMode === 'focus' ? 25 * 60 : 5 * 60);
    }
    setTimerActive(true);
  };

  const pauseTimer = () => setTimerActive(false);
  const resetTimer = () => {
    setTimerActive(false);
    setTimerSeconds(timerMode === 'focus' ? 25 * 60 : 5 * 60);
  };
  const switchMode = () => {
    setTimerActive(false);
    setTimerMode(prev => prev === 'focus' ? 'break' : 'focus');
    setTimerSeconds(0);
  };

  const formatTime = (seconds) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const getTypeIcon = (type) => {
    switch(type) {
      case 'exam': return <FaBook size={14} color="#e74c3c" />;
      case 'assignment': return <FaClipboardList size={14} color="#f39c12" />;
      case 'club': return <FaUsers size={14} color="#2ecc71" />;
      case 'work': return <FaBriefcase size={14} color="#3498db" />;
      default: return <FaBriefcase size={14} />;
    }
  };

  const getTypeLabel = (type) => {
    switch(type) {
      case 'exam': return 'Exam';
      case 'assignment': return 'Assignment';
      case 'club': return 'Club';
      case 'work': return 'Work';
      default: return 'Task';
    }
  };

  const getPriorityColor = (priority) => {
    if (priority === 'high') return '#e74c3c';
    if (priority === 'medium') return '#f39c12';
    return '#2ecc71';
  };

  const getPriorityEmoji = (priority) => {
    if (priority === 'high') return '🔴';
    if (priority === 'medium') return '🟡';
    return '🟢';
  };

  const upcomingItems = items.filter(i => !i.completed).sort((a,b) => new Date(a.dueDate) - new Date(b.dueDate));
  const completedItems = items.filter(i => i.completed);
  
  const getStressIcon = () => {
    if (stressLevel === 'high') return <FaFrown size={18} color="#e74c3c" />;
    if (stressLevel === 'medium') return <FaMeh size={18} color="#f39c12" />;
    return <FaSmile size={18} color="#2ecc71" />;
  };

  const getStressMessage = () => {
    if (stressLevel === 'high') return 'Take a break soon';
    if (stressLevel === 'medium') return 'Stay balanced';
    return 'Doing great!';
  };

  const types = [
    { value: 'exam', label: '📚 Exam', color: '#e74c3c' },
    { value: 'assignment', label: '📝 Assignment', color: '#f39c12' },
    { value: 'club', label: '🎯 Club', color: '#2ecc71' },
    { value: 'work', label: '💼 Work', color: '#3498db' },
  ];

  return (
    <div style={styles.container}>
      <Navbar />
      <div style={styles.navSpacer} />
      
      <div style={styles.content}>
        {/* Header with Gradient */}
        <div style={styles.header}>
          <h1 style={styles.title}>📚 Academic Load</h1>
          <p style={styles.subtitle}>Track tasks & stay focused</p>
        </div>

        {/* AI Insight Card */}
        <div style={styles.aiCard}>
          <div style={styles.aiIcon}><FaBrain size={20} color="#667eea" /></div>
          <div style={styles.aiContent}>
            <span style={styles.aiLabel}>✨ AI Insight</span>
            <p style={styles.aiText}>{aiInsight || "Loading insights..."}</p>
          </div>
        </div>

        {/* Stats Grid */}
        <div style={styles.statsGrid}>
          <div style={styles.statCard}>
            <div style={styles.statIcon}><FaFire color="#e74c3c" /></div>
            <div style={styles.statValue}>{items.filter(i => !i.completed).length}</div>
            <div style={styles.statLabel}>Pending</div>
          </div>
          <div style={styles.statCard}>
            <div style={styles.statIcon}><FaCheckCircle color="#2ecc71" /></div>
            <div style={styles.statValue}>{completedItems.length}</div>
            <div style={styles.statLabel}>Done</div>
          </div>
          <div style={styles.statCard}>
            <div style={styles.statIcon}><FaChartLine color="#3498db" /></div>
            <div style={styles.statValue}>{items.length}</div>
            <div style={styles.statLabel}>Total</div>
          </div>
          <div style={styles.statCard}>
            <div style={styles.statIcon}>{getStressIcon()}</div>
            <div style={styles.statValue}>{completionRate}%</div>
            <div style={styles.statLabel}>{getStressMessage()}</div>
          </div>
        </div>

        {/* Progress Bar */}
        <div style={styles.progressCard}>
          <div style={styles.progressHeader}>
            <span>📊 Weekly Progress</span>
            <span>{completionRate}% Complete</span>
          </div>
          <div style={styles.progressBarBg}>
            <div style={{...styles.progressBarFill, width: `${completionRate}%`}} />
          </div>
        </div>

        {/* Focus Timer Section */}
        <div style={styles.timerCard}>
          <div style={styles.timerHeader}>
            <FaStopwatch size={18} color="#667eea" />
            <span style={styles.timerTitle}>Focus Timer</span>
            <div style={styles.timerModeSwitch}>
              <button 
                onClick={() => { switchMode(); setTimerSeconds(0); }}
                style={{...styles.modeBtn, background: timerMode === 'focus' ? '#667eea' : '#f0f0f0', color: timerMode === 'focus' ? 'white' : '#555'}}
              >
                🎯 Focus
              </button>
              <button 
                onClick={() => { switchMode(); setTimerSeconds(0); }}
                style={{...styles.modeBtn, background: timerMode === 'break' ? '#2ecc71' : '#f0f0f0', color: timerMode === 'break' ? 'white' : '#555'}}
              >
                ☕ Break
              </button>
            </div>
          </div>
          <div style={styles.timerDisplay}>
            <span style={styles.timerTime}>{formatTime(timerSeconds || (timerMode === 'focus' ? 25 * 60 : 5 * 60))}</span>
          </div>
          <div style={styles.timerControls}>
            {!timerActive ? (
              <button onClick={startTimer} style={styles.timerPlayBtn}><FaPlay /> Start</button>
            ) : (
              <button onClick={pauseTimer} style={styles.timerPauseBtn}><FaPause /> Pause</button>
            )}
            <button onClick={resetTimer} style={styles.timerResetBtn}><FaRedo /> Reset</button>
          </div>
          <p style={styles.timerHint}>{timerMode === 'focus' ? 'Stay focused on your tasks!' : 'Take a well-deserved break'}</p>
        </div>

        {/* Add Task Button */}
        <button onClick={() => setShowAddForm(true)} style={styles.addBtn}>
          <FaPlus size={14} /> Add New Task
        </button>

        {/* Upcoming Tasks */}
        <div style={styles.taskSection}>
          <h3 style={styles.sectionTitle}>⏰ Upcoming Tasks</h3>
          {upcomingItems.length === 0 && <div style={styles.emptyState}>✨ No pending tasks. Great job! ✨</div>}
          {upcomingItems.map(item => (
            <div key={item.id} style={{...styles.taskCard, borderLeft: `4px solid ${getPriorityColor(item.priority)}`}}>
              <div style={styles.taskLeft}>
                <div onClick={() => toggleComplete(item.id)} style={styles.taskCheck}>
                  {item.completed ? <FaCheckCircle color="#2ecc71" size={20} /> : <FaCircle color="#ccc" size={20} />}
                </div>
                <div style={styles.taskTypeIcon}>{getTypeIcon(item.type)}</div>
                <div style={styles.taskDetails}>
                  <div style={styles.taskTitleRow}>
                    <span style={styles.taskName}>{getTypeLabel(item.type)}: {item.title}</span>
                    <span style={styles.taskPriority}>{getPriorityEmoji(item.priority)}</span>
                  </div>
                  <div style={styles.taskMeta}>
                    <FaCalendarAlt size={10} color="#999" />
                    <span>{new Date(item.dueDate).toLocaleDateString()}</span>
                    {item.dueTime && <><FaClock size={10} color="#999" /><span>{item.dueTime}</span></>}
                  </div>
                </div>
              </div>
              <button onClick={() => deleteItem(item.id)} style={styles.deleteBtn}><FaTrash size={14} /></button>
            </div>
          ))}
        </div>

        {/* Completed Tasks */}
        {completedItems.length > 0 && (
          <div style={styles.taskSection}>
            <h3 style={styles.sectionTitle}>✅ Completed ({completedItems.length})</h3>
            {completedItems.slice(0, 4).map(item => (
              <div key={item.id} style={{...styles.taskCard, opacity: 0.7, background: '#f0fff0'}}>
                <div style={styles.taskLeft}>
                  <div onClick={() => toggleComplete(item.id)} style={styles.taskCheck}>
                    <FaCheckCircle color="#2ecc71" size={20} />
                  </div>
                  <div style={styles.taskTypeIcon}>{getTypeIcon(item.type)}</div>
                  <div style={styles.taskDetails}>
                    <span style={{...styles.taskName, textDecoration: 'line-through'}}>{item.title}</span>
                  </div>
                </div>
                <button onClick={() => deleteItem(item.id)} style={styles.deleteBtn}><FaTrash size={14} /></button>
              </div>
            ))}
            {completedItems.length > 4 && <p style={styles.viewMore}>+{completedItems.length - 4} more completed</p>}
          </div>
        )}

        {/* Add Task Modal */}
        {showAddForm && (
          <div style={styles.modal} onClick={() => setShowAddForm(false)}>
            <div style={styles.modalContent} onClick={(e) => e.stopPropagation()}>
              <h3 style={styles.modalTitle}>➕ Add New Task</h3>
              
              <input 
                type="text" 
                placeholder="What needs to be done?" 
                value={newItem.title} 
                onChange={(e) => setNewItem({...newItem, title: e.target.value})} 
                style={styles.modalInput} 
                autoFocus
              />
              
              <div style={styles.typeGrid}>
                {types.map(t => (
                  <button 
                    key={t.value} 
                    onClick={() => setNewItem({...newItem, type: t.value})} 
                    style={{...styles.typeBtn, background: newItem.type === t.value ? t.color : '#f5f5f5', color: newItem.type === t.value ? 'white' : '#555'}}
                  >
                    {t.label}
                  </button>
                ))}
              </div>
              
              <div style={styles.modalRow}>
                <input 
                  type="date" 
                  value={newItem.dueDate} 
                  onChange={(e) => setNewItem({...newItem, dueDate: e.target.value})} 
                  style={styles.modalHalfInput} 
                  placeholder="Due date"
                />
                <input 
                  type="time" 
                  value={newItem.dueTime} 
                  onChange={(e) => setNewItem({...newItem, dueTime: e.target.value})} 
                  style={styles.modalHalfInput} 
                  placeholder="Time"
                />
              </div>
              
              <div style={styles.priorityGrid}>
                <button onClick={() => setNewItem({...newItem, priority: 'low'})} style={{...styles.priorityBtn, background: newItem.priority === 'low' ? '#2ecc71' : '#f5f5f5', color: newItem.priority === 'low' ? 'white' : '#555'}}>🟢 Low</button>
                <button onClick={() => setNewItem({...newItem, priority: 'medium'})} style={{...styles.priorityBtn, background: newItem.priority === 'medium' ? '#f39c12' : '#f5f5f5', color: newItem.priority === 'medium' ? 'white' : '#555'}}>🟡 Medium</button>
                <button onClick={() => setNewItem({...newItem, priority: 'high'})} style={{...styles.priorityBtn, background: newItem.priority === 'high' ? '#e74c3c' : '#f5f5f5', color: newItem.priority === 'high' ? 'white' : '#555'}}>🔴 High</button>
              </div>
              
              <div style={styles.modalActions}>
                <button onClick={addItem} style={styles.saveBtn}>Save Task</button>
                <button onClick={() => setShowAddForm(false)} style={styles.cancelBtn}>Cancel</button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

